const digest = 'a'.repeat(64)
const sourceHash = 'b'.repeat(64)
const copyHash = 'c'.repeat(64)

const exposure = (
  exposureId: string,
  actorId: string,
  catalogKey: string,
  surface: 'browse' | 'category' | 'search',
  rank: number,
  issuedAt: string,
  options: Partial<BlueprintMeasurementReadinessInput['exposures'][number]> = {}
): BlueprintMeasurementReadinessInput['exposures'][number] => ({
  actorId,
  exposureId,
  catalogKey,
  sourceRevision: 1,
  sourceContentHash: sourceHash,
  surface,
  rank,
  issuedAt,
  expiresAt: new Date(Date.parse(issuedAt) + 30 * 60 * 1000).toISOString(),
  rankingContext: {
    mode: 'baseline_v1',
    algorithmVersion: 'blueprint-baseline-v1',
    configurationVersion: 'blueprint-baseline-v1',
    configurationDigest: digest,
  },
  actorDisposition: 'eligible',
  consent: 'enabled',
  exactSourceStatus: 'current',
  ...options,
})

function validAcquisition(
  acquisitionId: string,
  actorId: string,
  exposureId: string,
  sourceCatalogKey: string,
  acquiredAt: string,
  expiresAt: string
): BlueprintMeasurementReadinessInput['acquisitions'][number] {
  return {
    acquisitionId,
    actorId,
    exposureId,
    sourceCatalogKey,
    sourceRevision: 1,
    sourceContentHash: sourceHash,
    copyContentHash: copyHash,
    copyRevisionMatchesHash: true,
    acquiredAt,
    expiresAt,
  }
}

